package com.example.starter.slam.domain;

/**
 * 边类型：里程计边或回环约束边。
 */
public enum EdgeType {
    /**
     * 相邻关键帧之间的里程计约束。
     */
    ODOMETRY,
    /**
     * 非相邻关键帧之间的回环约束。
     */
    LOOP
}

package com.example.starter.slam.domain;

/**
 * 边的审计状态：有效进入位姿图，或回环校验未通过被拒绝（仅审计留存）。
 */
public enum EdgeStatus {
    /**
     * 校验通过并进入有效图，参与图版本递增。
     */
    VALID,
    /**
     * 回环约束未通过版本化阈值校验，仅保存审计记录，不进入有效图。
     */
    REJECTED
}

package com.example.starter.slam.domain;

/**
 * 优化任务状态。
 */
public enum TaskStatus {
    /**
     * 待执行：可与同一图上后续尚未开始的请求合并。
     */
    PENDING,
    /**
     * 运行中：已被工作线程领取，快照固定，不再参与合并。
     */
    RUNNING,
    /**
     * 成功：结果已落库且为当前最新有效结果。
     */
    SUCCEEDED,
    /**
     * 可重试失败：保留输入快照、失败原因与重试次数，可按原快照重试。
     */
    FAILED_RETRYABLE,
    /**
     * 已被取代：已有基于更高图版本（更多有效边）的成功结果，本结果不得覆盖新结果。
     */
    SUPERSEDED
}

package com.example.starter.slam.web;

/**
 * 同 ID 或同 requestId 改参等冲突，映射 HTTP 409。
 */
public class ConflictException extends RuntimeException {

    public ConflictException(String message) {
        super(message);
    }
}

package com.example.starter.slam.web;

/**
 * 请求引用的实体不存在（例如边引用了不存在的关键帧），映射 HTTP 404。
 */
public class NotFoundException extends RuntimeException {

    public NotFoundException(String message) {
        super(message);
    }
}

