package com.example.starter.slam.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.util.List;

/**
 * 关键帧写入请求。
 *
 * @param id      全局唯一关键帧 ID
 * @param source  数据来源（如 odometry/camera 等）
 * @param version 数据版本
 * @param pose    位姿测量数据 [x, y, theta]，单位米/弧度，坐标系由来源约定
 */
public record KeyFrameRequest(
        @NotBlank String id,
        @NotBlank String source,
        long version,
        @NotNull List<Double> pose
) {
}

package com.example.starter.slam.api;

import com.example.starter.slam.domain.EdgeType;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.util.List;

/**
 * 边写入请求（里程计边或回环约束）。
 *
 * @param id          全局唯一边 ID
 * @param requestId   客户端幂等键；同 ID 或同 requestId 改参返回 409
 * @param source      数据来源
 * @param version     数据版本
 * @param type        边类型 ODOMETRY / LOOP
 * @param fromFrameId 起点关键帧 ID，必须已存在
 * @param toFrameId   终点关键帧 ID，必须已存在
 * @param measurement 相对位姿测量 [dx, dy, dtheta]，单位米/弧度
 * @param information 信息矩阵（3x3 按行展开的 9 个值），用于回环协方差检查
 * @param score       回环匹配分数（0~1，越高越可信）；里程计边可为 null
 * @param residual    回环初始残差，单位与测量一致；里程计边可为 null
 */
public record EdgeRequest(
        @NotBlank String id,
        @NotBlank String requestId,
        @NotBlank String source,
        long version,
        @NotNull EdgeType type,
        @NotBlank String fromFrameId,
        @NotBlank String toFrameId,
        @NotNull List<Double> measurement,
        List<Double> information,
        Double score,
        Double residual
) {
}

package com.example.starter.slam.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 优化提交请求。
 *
 * @param requestId 客户端幂等键，重复提交返回同一任务
 * @param graphId   目标图 ID
 */
public record OptimizeRequest(
        @NotBlank String requestId,
        @NotBlank String graphId
) {
}

package com.example.starter.slam.api;

import com.example.starter.slam.domain.EdgeStatus;
import com.example.starter.slam.domain.EdgeType;

import java.time.Instant;

/**
 * 关键帧写入响应。
 */
public record KeyFrameView(
        String id,
        String source,
        long version,
        String graphId,
        long graphVersion,
        boolean duplicated,
        Instant createdAt
) {
}

