package com.example.starter.slam.optim;

import com.example.starter.slam.domain.EdgeType;

import java.util.List;

/**
 * 优化输入中单条有效边的不可变快照（仅 VALID 边入图）。
 *
 * @param id          边 ID
 * @param source      数据来源
 * @param version     数据版本
 * @param type        边类型
 * @param fromFrameId 起点关键帧 ID
 * @param toFrameId   终点关键帧 ID
 * @param measurement 相对位姿测量 [dx, dy, dtheta]
 * @param information 信息矩阵（3x3 按行展开 9 个值）
 */
public record EdgeSnapshot(
        String id,
        String source,
        long version,
        EdgeType type,
        String fromFrameId,
        String toFrameId,
        List<Double> measurement,
        List<Double> information
) {
}

package com.example.starter.slam.optim;

import java.util.List;

/**
 * 优化任务执行时固定的图输入快照。重试必须复用同一快照。
 *
 * @param graphId      图 ID
 * @param graphVersion 快照对应的有效图版本
 * @param frames       全部关键帧快照（按 ID 排序）
 * @param edges        全部有效边快照（按 ID 排序，不含 REJECTED 回环）
 */
public record GraphSnapshot(
        String graphId,
        long graphVersion,
        List<FrameSnapshot> frames,
        List<EdgeSnapshot> edges
) {

    /**
     * 生成可持久化的快照摘要，用于失败审计与任务展示。
     *
     * @return 摘要字符串
     */
    public String summary() {
        return "graph=" + graphId
                + ",version=" + graphVersion
                + ",frames=" + frames.size()
                + ",edges=" + edges.size();
    }
}

package com.example.starter.slam.optim;

import java.util.List;
