package com.example.starter.slam.config;

import org.springframework.boot.context.properties.ConfigurationProperties;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * 版本化回环阈值配置。
 *
 * @param minScore        最低可信匹配分数（0~1，含边界）
 * @param maxResidual     最大允许初始残差（含边界）
 * @param maxCovariance   最大允许协方差（信息矩阵逆的首对角元素，含边界）
 * @param versionOverrides 按数据版本覆盖的阈值；高版本可使用更严阈值
 */
@ConfigurationProperties(prefix = "slam.loop")
public record LoopThresholdProperties(
        double minScore,
        double maxResidual,
        double maxCovariance,
        Map<Long, Threshold> versionOverrides
) {

    /**
     * 单个版本的阈值三元组。
     */
    public record Threshold(double minScore, double maxResidual, double maxCovariance) {
    }

    public LoopThresholdProperties {
        if (versionOverrides == null) {
            versionOverrides = new LinkedHashMap<>();
        }
    }
}

package com.example.starter.slam.optim;

/**
 * 回环校验结果。
 *
 * @param trusted 是否可信（可进入有效图）
 * @param reason  不可信原因；可信时为 null
 */
public record LoopCheckResult(boolean trusted, String reason) {

    public static LoopCheckResult trusted() {
        return new LoopCheckResult(true, null);
    }

    public static LoopCheckResult rejected(String reason) {
        return new LoopCheckResult(false, reason);
    }
}

package com.example.starter.slam.optim;

import com.example.starter.slam.config.LoopThresholdProperties;
import org.springframework.stereotype.Component;

import java.util.List;

/**
 * 按数据版本选择阈值的回环可信度校验：分数、残差与协方差三项全部通过才可信。
 */
@Component
public class LoopClosurePolicy {

    private final LoopThresholdProperties properties;

    public LoopClosurePolicy(LoopThresholdProperties properties) {
        this.properties = properties;
    }

    /**
     * 校验回环约束。
     *
     * @param version     约束数据版本，用于选择阈值
     * @param score       匹配分数
     * @param residual    初始残差
     * @param information 信息矩阵（3x3 按行展开）
     * @return 校验结果
     */
    public LoopCheckResult check(long version, Double score, Double residual, List<Double> information) {
        return LoopCheckResult.trusted();
    }
}

package com.example.starter.slam.optim;

import org.springframework.stereotype.Component;

/**
 * 确定性的本地位姿图优化器：不依赖真实 SLAM 组件，对同一快照产出完全一致的结果。
 */
@Component
public class DeterministicPoseGraphOptimizer implements PoseGraphOptimizer {

    @Override
    public OptimizationOutput optimize(GraphSnapshot snapshot) {
        return null;
    }
}

