                             @Value("${slam.queue.poll-millis:50}") long pollMillis) {
        this.taskStore = taskStore;
        this.graphStore = graphStore;
        this.optimizer = optimizer;
        this.pollMillis = pollMillis;
    }

    /**
     * 通知工作线程有待执行任务（提交/重试后唤醒，降低延迟）。
     */
    public void signal() {
    }

    @PostConstruct
    void start() {
    }

    @PreDestroy
    void stop() {
    }
}

